from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .esp_niche import require_esp_social_member

router = APIRouter()


@router.get("/command-center/social-insights", response_class=HTMLResponse, include_in_schema=False)
def social_insights(request: Request):
    _member, membership, profile = require_esp_social_member(request)
    definition = profile["catalog"]
    accent = definition["theme"]["accent"]
    secondary = definition["theme"]["secondary"]
    niche = definition["title"]
    role = membership.get("roles") or ("owner" if membership.get("status") == "owner" else "member")
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='robots' content='noindex,nofollow'><title>ESP Social Intelligence</title><style>
:root{--accent:__ACCENT__;--secondary:__SECONDARY__;--bg:#04050b;--panel:#101320;--line:#ffffff1d;--text:#fff;--muted:#bcc0d2;--good:#76dda1;--warn:#ffd17b}*{box-sizing:border-box}body{margin:0;color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:radial-gradient(circle at 8% 0,var(--secondary),transparent 30%),radial-gradient(circle at 92% 5%,var(--accent),transparent 22%),#04050b;min-height:100vh}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.wrap{width:min(1420px,calc(100% - 28px));margin:auto;padding:24px 0 55px}.top,.row{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.eyebrow{color:var(--accent);font-size:.72rem;font-weight:950;letter-spacing:.16em;text-transform:uppercase}h1{font-size:clamp(2.5rem,6vw,5rem);letter-spacing:-.055em;line-height:.94;margin:.15em 0}.muted{color:var(--muted);line-height:1.55}.btn{display:inline-block;border:1px solid var(--line);border-radius:11px;padding:9px 12px;background:#ffffff08;color:#fff;font-weight:850;cursor:pointer}.primary{border:0;background:linear-gradient(110deg,var(--accent),var(--secondary));color:#130a19}.layout{display:grid;grid-template-columns:260px 1fr;gap:13px}.side,.panel,.card{border:1px solid var(--line);border-radius:19px;background:linear-gradient(145deg,#111426e8,#080a13ed);padding:15px}.side{height:max-content;position:sticky;top:15px}.space{border:1px solid var(--line);border-radius:12px;padding:10px;margin:7px 0;cursor:pointer;background:#ffffff05}.space.active{border-color:var(--accent)}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:13px}.tab{border:1px solid var(--line);border-radius:999px;padding:7px 10px;background:#ffffff05;color:#fff;font-weight:800;cursor:pointer}.tab.active{border-color:var(--accent);background:#ffffff10}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.metric{border:1px solid var(--line);border-radius:14px;padding:12px;background:#ffffff05}.metric b{display:block;font-size:1.45rem}.field{width:100%;border:1px solid var(--line);background:#070912;color:#fff;border-radius:10px;padding:10px}textarea.field{min-height:100px}.stack{display:grid;gap:8px}.item{border:1px solid var(--line);border-radius:14px;padding:12px;background:#ffffff04;margin:8px 0}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 7px;font-size:.68rem;margin:2px}.good{color:var(--good)}.notice{display:none;border:1px solid var(--line);border-radius:11px;padding:10px;margin-bottom:10px}.notice.show{display:block}.empty{border:1px dashed #ffffff28;border-radius:13px;padding:20px;text-align:center;color:var(--muted)}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{position:relative}.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid,.grid2{grid-template-columns:1fr}}
</style></head><body><main class='wrap'><header class='top'><div><div class='eyebrow'>Elevate Souls Productions · __NICHE__</div><h1>Aura Social Intelligence</h1><p class='muted'>Private ESP analytics, calendar, approvals and media intelligence. Role: __ROLE__. This is not available to ordinary Pulsar-Frequency House members.</p></div><div><a class='btn' href='/command-center/social'>Social Management</a> <a class='btn' href='/command-center'>ESP Hub</a></div></header><div id='notice' class='notice'></div><section class='layout'><aside class='side'><div class='eyebrow'>Social Houses</div><div id='spaces'><div class='empty'>Loading…</div></div><p class='muted' style='font-size:.78rem'>Create and edit Social Houses from the main Social Management workspace.</p></aside><section class='panel'><div class='tabs'><button class='tab active' onclick="tab('insights',this)">Aura Insights</button><button class='tab' onclick="tab('calendar',this)">Calendar</button><button class='tab' onclick="tab('analytics',this)">Analytics</button><button class='tab' onclick="tab('media',this)">Media Library</button><button class='tab' onclick="tab('approvals',this)">Approvals</button></div><div id='content'><div class='empty'>Choose a Social House.</div></div></section></section></main><script>
const S='/command-center/api/social',I='/command-center/api/social-intelligence';let spaces=[],house=null,active='insights';const q=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function notice(m){const n=q('notice');n.textContent=m;n.className='notice show';clearTimeout(window.__n);window.__n=setTimeout(()=>n.className='notice',6000)}async function api(base,path,opt={}){const r=await fetch(base+path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opt});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}async function load(){const d=await api(S,'/spaces');spaces=d.spaces||[];renderSpaces();if(spaces.length)openSpace(spaces[0].id)}function renderSpaces(){q('spaces').innerHTML=spaces.length?spaces.map(s=>`<div class="space ${house?.id===s.id?'active':''}" onclick="openSpace('${s.id}')"><b>${esc(s.name)}</b><div class="muted">${esc(s.description||'ESP Social House')}</div></div>`).join(''):'<div class="empty">No Social Houses yet.</div>'}async function openSpace(id){house=await api(S,`/spaces/${encodeURIComponent(id)}`);renderSpaces();render()}function tab(name,el){active=name;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');render()}async function render(){if(!house)return;try{if(active==='insights')return renderInsights();if(active==='calendar')return renderCalendar();if(active==='analytics')return renderAnalytics();if(active==='media')return renderMedia();if(active==='approvals')return renderApprovals()}catch(e){notice(e.message)}}async function renderInsights(){const d=await api(I,`/spaces/${house.id}/aura-insights`);q('content').innerHTML=`<div class="grid"><div class="metric"><b>${d.snapshot_count}</b><small>Analytics snapshots</small></div><div class="metric"><b>${d.platforms.length}</b><small>Platforms measured</small></div><div class="metric"><b>${house.content.length}</b><small>Content items</small></div><div class="metric"><b>${house.content.filter(x=>x.status==='published').length}</b><small>Published</small></div></div><div class="card" style="margin-top:10px"><div class="eyebrow">Aura recommendations</div>${d.recommendations.length?'<ol>'+d.recommendations.map(x=>`<li class="muted" style="margin:8px 0">${esc(x)}</li>`).join('')+'</ol>':'<p class="muted">Add analytics to generate recommendations.</p>'}</div><div class="card" style="margin-top:10px"><div class="eyebrow">Measured averages</div>${Object.entries(d.averages||{}).map(([k,v])=>`<span class="pill">${esc(k.replaceAll('_',' '))}: ${esc(v)}</span>`).join('')||'<span class="muted">No numeric metrics yet.</span>'}</div>`}async function renderCalendar(){const d=await api(I,`/spaces/${house.id}/calendar`);q('content').innerHTML=`<div class="eyebrow">Scheduled content</div><h2>${esc(house.name)} Calendar</h2>${d.entries.length?d.entries.map(x=>`<div class="item"><div class="row"><b>${esc(x.title)}</b><span class="pill">${esc(x.platform)}</span></div><div class="muted">${esc(x.scheduled_at)} · ${esc(x.content_type)} · ${esc(x.status)}</div></div>`).join(''):'<div class="empty">No scheduled platform variants yet.</div>'}` }async function renderAnalytics(){const d=await api(I,`/spaces/${house.id}/analytics`);q('content').innerHTML=`<div class="grid2"><div class="card"><div class="eyebrow">Add performance snapshot</div><div class="stack"><select id="aPlatform" class="field"><option>tiktok</option><option>instagram</option><option>youtube</option><option>facebook</option><option>threads</option><option>x</option></select><input id="aPeriod" class="field" placeholder="Period / campaign label"><textarea id="aMetrics" class="field" placeholder='Metrics as JSON, e.g. {"views":1200,"completion_rate":48,"shares":12}'></textarea><button class="btn primary" onclick="addAnalytics()">Save analytics</button></div></div><div class="card"><div class="eyebrow">Why upload data?</div><p class="muted">Aura combines these results with the creator's selected ESP niche and training priorities to recommend what to repeat, change or test next.</p></div></div><h3>History</h3>${d.snapshots.length?d.snapshots.map(x=>`<div class="item"><div class="row"><b>${esc(x.platform)}</b><span class="pill">${esc(x.period_label||'snapshot')}</span></div><div>${Object.entries(x.metrics||{}).map(([k,v])=>`<span class="pill">${esc(k)}: ${esc(v)}</span>`).join('')}</div></div>`).join(''):'<div class="empty">No social analytics saved yet.</div>'}` }async function addAnalytics(){let metrics={};try{metrics=JSON.parse(q('aMetrics').value||'{}')}catch(e){return notice('Metrics must be valid JSON.')}await api(I,`/spaces/${house.id}/analytics`,{method:'POST',body:JSON.stringify({platform:q('aPlatform').value,period_label:q('aPeriod').value,metrics})});notice('Analytics saved. Aura insights updated.');renderAnalytics()}async function renderMedia(){const d=await api(I,`/spaces/${house.id}/media`);q('content').innerHTML=`<div class="grid2"><div class="card"><div class="eyebrow">Register authorised media</div><div class="stack"><input id="mLabel" class="field" placeholder="Media label"><select id="mKind" class="field"><option>image</option><option>video</option><option>audio</option><option>document</option><option>creative_project</option><option>other</option></select><input id="mRef" class="field" placeholder="Project asset/reference ID"><input id="mFolder" class="field" placeholder="Folder / collection"><label class="muted"><input id="mRights" type="checkbox"> I own or am authorised to use this media.</label><button class="btn primary" onclick="addMedia()">Add to media library</button></div></div><div class="card"><div class="eyebrow">Media principle</div><p class="muted">The Social Hub stores references and rights metadata here. Raw social OAuth tokens are never stored in Social House documents.</p></div></div><h3>Media library</h3>${d.media.length?d.media.map(x=>`<div class="item"><div class="row"><b>${esc(x.label)}</b><span class="pill">${esc(x.kind)}</span></div><div class="muted">${esc(x.folder||'Unfiled')} · ${esc(x.source_ref)}</div></div>`).join(''):'<div class="empty">No authorised media registered yet.</div>'}` }async function addMedia(){if(!q('mRights').checked)return notice('Rights confirmation is required.');await api(I,`/spaces/${house.id}/media`,{method:'POST',body:JSON.stringify({label:q('mLabel').value,kind:q('mKind').value,source_ref:q('mRef').value,folder:q('mFolder').value,rights_confirmed:true,tags:[]})});notice('Media added.');renderMedia()}async function renderApprovals(){const pending=house.content.filter(x=>x.approval_required||x.status==='pending_approval');if(!pending.length){q('content').innerHTML='<div class="empty">No content currently requires approval.</div>';return}q('content').innerHTML=`<div class="eyebrow">Approval conversations</div><h2>Content awaiting review</h2>${pending.map(x=>`<div class="item"><div class="row"><b>${esc(x.title)}</b><span class="pill">${esc(x.status)}</span></div><div id="comments_${x.id}" class="muted">Load comments to review discussion.</div><div class="row" style="margin-top:8px"><button class="btn" onclick="loadComments('${x.id}')">Load comments</button><button class="btn primary" onclick="approve('${x.id}')">Approve content</button></div></div>`).join('')}` }async function loadComments(id){const d=await api(I,`/spaces/${house.id}/content/${id}/comments`);q(`comments_${id}`).innerHTML=d.comments.length?d.comments.map(c=>`<div class="item"><b>${esc(c.author)}</b> <span class="pill">${esc(c.visibility)}</span><div>${esc(c.body)}</div></div>`).join(''):'No comments yet.'}async function approve(id){await api(S,`/spaces/${house.id}/content/${id}/approve`,{method:'POST',body:JSON.stringify({approver:'ESP approved member'})});house=await api(S,`/spaces/${house.id}`);notice('Content approved.');renderApprovals()}load().catch(e=>notice(e.message));
</script></body></html>"""
    return HTMLResponse(
        html.replace("__ACCENT__", accent)
        .replace("__SECONDARY__", secondary)
        .replace("__NICHE__", escape(niche))
        .replace("__ROLE__", escape(str(role).replace("both", "Creator + Agent").title()))
    )
